<script setup>defineProps({modelValue:Boolean,label:String,description:String,disabled:Boolean});defineEmits(['update:modelValue'])</script><template><label class="switch"><span><b>{{label}}</b><small>{{description}}</small></span><button type="button" role="switch" :aria-checked="modelValue" :disabled="disabled" :class="{on:modelValue}" @click="$emit('update:modelValue',!modelValue)"><i/></button></label></template><style scoped>.switch{display:flex;align-items:center;justify-content:space-between;gap:16px;color:var(--text-primary);font:400 14px var(--font-core)}b,small{display:block}b{font-weight:600}small{margin-top:3px;color:var(--text-muted);font-size:12px}button{width:48px;height:28px;padding:3px;border:0;border-radius:99px;background:var(--progress-none)}button i{display:block;width:22px;height:22px;border-radius:50%;background:var(--text-muted);transition:.2s}.on{background:var(--action-primary)}.on i{transform:translateX(20px);background:var(--action-primary-fg)}</style>
